create extension if not exists pgcrypto;
create table if not exists customers (id uuid primary key default gen_random_uuid(), company_name text not null, customer_type text default 'company', tax_number text, address text, billing_address text, phone text, email text, contact_person text, notes text, created_at timestamptz default now());
create table if not exists quotes (id uuid primary key default gen_random_uuid(), quote_number text unique not null, customer_id uuid references customers(id), project_name text, location text, quote_date date default current_date, valid_until date, status text default 'draft', net_total numeric(14,2) default 0, vat_total numeric(14,2) default 0, gross_total numeric(14,2) default 0, notes text, created_at timestamptz default now());
create table if not exists quote_items (id uuid primary key default gen_random_uuid(), quote_id uuid references quotes(id) on delete cascade, description text not null, category text, quantity numeric(14,3) default 1, unit text, unit_price numeric(14,2) default 0, vat_rate numeric(5,2) default 27, net_total numeric(14,2) default 0, vat_total numeric(14,2) default 0, gross_total numeric(14,2) default 0);
create table if not exists projects (id uuid primary key default gen_random_uuid(), project_number text unique not null, customer_id uuid references customers(id), quote_id uuid references quotes(id), name text not null, location text, latitude numeric(10,7), longitude numeric(10,7), start_date date, planned_end_date date, actual_end_date date, status text default 'interest', contract_value numeric(14,2) default 0, planned_cost numeric(14,2) default 0, actual_cost numeric(14,2) default 0, profit numeric(14,2) generated always as (contract_value-actual_cost) stored, profit_margin numeric(7,3) generated always as (case when contract_value>0 then ((contract_value-actual_cost)/contract_value)*100 else 0 end) stored, responsible_user_id uuid, created_at timestamptz default now());
create table if not exists employees (id uuid primary key default gen_random_uuid(), name text not null, role text, phone text, hourly_rate numeric(12,2) default 0, active boolean default true);
create table if not exists machines (id uuid primary key default gen_random_uuid(), machine_number text unique not null, name text not null, manufacturer text, model text, serial_number text, year int, current_hours numeric(12,1) default 0, status text default 'active', purchase_date date, purchase_price numeric(14,2), notes text);
create table if not exists products (id uuid primary key default gen_random_uuid(), sku text unique not null, name text not null, category text, unit text, purchase_price numeric(14,2) default 0, sale_price numeric(14,2) default 0, vat_rate numeric(5,2) default 27, minimum_stock numeric(14,3) default 0, material_type text, diameter_mm numeric(10,2), length_m numeric(10,3), material_unit text default 'db');
create table if not exists warehouses (id uuid primary key default gen_random_uuid(), name text not null);
create table if not exists warehouse_stock (warehouse_id uuid references warehouses(id) on delete cascade, product_id uuid references products(id) on delete cascade, quantity numeric(14,3) default 0, primary key (warehouse_id,product_id));
create table if not exists work_logs (id uuid primary key default gen_random_uuid(), project_id uuid references projects(id) on delete cascade, work_date date default current_date, start_time time, end_time time, description text, work_type text, depth_start numeric(10,2), depth_end numeric(10,2), weather text, notes text, created_at timestamptz default now());
create table if not exists project_material_requirements (id uuid primary key default gen_random_uuid(), project_id uuid not null references projects(id) on delete cascade, product_id uuid not null references products(id), required_qty numeric(14,3) not null default 0, required_unit text default 'db', reserved_qty numeric(14,3) not null default 0, used_qty numeric(14,3) not null default 0, status text default 'planned', notes text, created_at timestamptz default now(), unique(project_id,product_id));
create table if not exists project_material_usage (id uuid primary key default gen_random_uuid(), project_id uuid not null references projects(id) on delete cascade, product_id uuid not null references products(id), quantity numeric(14,3) not null, unit text default 'db', work_log_id uuid references work_logs(id) on delete set null, created_at timestamptz default now());
create table if not exists project_costs (id uuid primary key default gen_random_uuid(), project_id uuid references projects(id) on delete cascade, category text not null, description text, amount numeric(14,2) not null, cost_date date default current_date, source_type text, source_id uuid);
create table if not exists machine_usage (id uuid primary key default gen_random_uuid(), machine_id uuid references machines(id), project_id uuid references projects(id), usage_date date default current_date, start_hours numeric(12,1), end_hours numeric(12,1), hours numeric(12,1), cost numeric(14,2) default 0);
create table if not exists machine_service (id uuid primary key default gen_random_uuid(), machine_id uuid references machines(id) on delete cascade, service_date date, operating_hours numeric(12,1), service_type text, cost numeric(14,2) default 0, description text, next_service_hours numeric(12,1), next_service_date date);
create index if not exists idx_project_material_requirements_project on project_material_requirements(project_id);
create index if not exists idx_project_material_requirements_product on project_material_requirements(product_id);
create index if not exists idx_project_material_usage_project on project_material_usage(project_id);
create index if not exists idx_project_material_usage_product on project_material_usage(product_id);
